from pathlib import Path
import re

path = Path('apps/web-portal/components/policy-unified-form.tsx')
text = path.read_text(encoding='utf-8')

old_call = '<LiveSummary net={calculations.net} gst={calculations.gst} gross={calculations.gross} payinAfterTds={calculations.payinAfterTds} grossPayout={calculations.grossPayout}/>'
new_call = '<LiveSummary completion={Math.round(sectionProgress.reduce((sum,item)=>sum+item.filled,0)/sectionProgress.reduce((sum,item)=>sum+item.total,0)*100)} net={calculations.net} gst={calculations.gst} gross={calculations.gross} projectedOd={calculations.projectedOd} projectedTp={calculations.projectedTp} scheme={numeric(form.insurerScheme)} totalPayin={calculations.totalPayin} tds={calculations.tds} payinAfterTds={calculations.payinAfterTds} retention={calculations.indicativeMargin} grossPayout={calculations.grossPayout}/>'
if old_call not in text:
    raise SystemExit('LiveSummary call not found')
text = text.replace(old_call, new_call, 1)

pattern = r'function LiveSummary\([\s\S]*?function ValidationErrorDialog'
replacement = '''function CompletionRing({value}:{value:number}){const clamped=Math.max(0,Math.min(100,value));const radius=19,circumference=2*Math.PI*radius,offset=circumference-(clamped/100)*circumference;return <div className="relative h-12 w-12 shrink-0" aria-label={`${clamped}% complete`} title={`${clamped}% complete`}><svg viewBox="0 0 48 48" className="h-12 w-12 -rotate-90"><circle cx="24" cy="24" r={radius} fill="none" stroke="#E3EAF2" strokeWidth="5"/><circle cx="24" cy="24" r={radius} fill="none" stroke="url(#policyCompletionGradient)" strokeWidth="5" strokeLinecap="round" strokeDasharray={circumference} strokeDashoffset={offset}/><defs><linearGradient id="policyCompletionGradient" x1="0" y1="0" x2="48" y2="48" gradientUnits="userSpaceOnUse"><stop stopColor="#315B9A"/><stop offset="1" stopColor="#19B5A5"/></linearGradient></defs></svg><span className="absolute inset-0 grid place-items-center text-[9px] font-bold text-[#17365D]">{clamped}%</span></div>;}
function LiveSummary({completion,net,gst,gross,projectedOd,projectedTp,scheme,totalPayin,tds,payinAfterTds,retention,grossPayout}:{completion:number;net:number;gst:number;gross:number;projectedOd:number;projectedTp:number;scheme:number;totalPayin:number;tds:number;payinAfterTds:number;retention:number;grossPayout:number}){const anchorRef=useRef<HTMLDivElement>(null);const[position,setPosition]=useState<{left:number;width:number;top:number}|null>(null);useEffect(()=>{const updatePosition=()=>{if(window.innerWidth<1280||!anchorRef.current){setPosition(null);return;}const rect=anchorRef.current.getBoundingClientRect();setPosition({left:rect.left,width:rect.width,top:Math.max(rect.top,172)});};updatePosition();window.addEventListener("resize",updatePosition);window.addEventListener("scroll",updatePosition,true);const observer=new ResizeObserver(updatePosition);if(anchorRef.current)observer.observe(anchorRef.current);observer.observe(document.documentElement);return()=>{window.removeEventListener("resize",updatePosition);window.removeEventListener("scroll",updatePosition,true);observer.disconnect();};},[]);const complete=completion>=100;const card=<div className="overflow-hidden rounded-2xl border border-[#D9E2F0] bg-white shadow-[0_10px_30px_rgba(15,23,42,.10)]"><div className="flex items-center gap-3 border-b bg-[#F8FAFC] px-4 py-3"><div className="min-w-0 flex-1"><p className="text-[8px] font-bold uppercase tracking-[.11em] text-[#64748B]">Policy status</p><h3 className="mt-0.5 truncate text-[13px] font-semibold text-[#17365D]">Onboarding summary</h3></div><CompletionRing value={completion}/><span className={`shrink-0 rounded-full px-2.5 py-1 text-[8px] font-bold ${complete?"bg-[#E8F7EF] text-[#14845B]":"bg-[#FFF3CD] text-[#A96A00]"}`}>{complete?"Complete":"In progress"}</span></div><div className="p-4"><p className="mb-2 text-[8px] font-bold uppercase tracking-[.1em] text-[#64748B]">Financial summary</p><div className="divide-y divide-[#E8EDF3]"><SummaryRow label="Net premium" value={money.format(net)}/><SummaryRow label="GST" value={money.format(gst)}/><SummaryRow label="Gross premium" value={money.format(gross)} bold accent/><SummaryRow label="Projected OD pay-in" value={money.format(projectedOd)}/><SummaryRow label="Projected TP pay-in" value={money.format(projectedTp)}/><SummaryRow label="Insurer scheme" value={money.format(scheme)}/><SummaryRow label="Total pay-in" value={money.format(totalPayin)} bold/><SummaryRow label="TDS" value={money.format(tds)}/><SummaryRow label="Pay-in after TDS" value={money.format(payinAfterTds)} bold/><SummaryRow label="Retention" value={money.format(retention)} tone={retention<0?"negative":retention>0?"positive":"neutral"}/><SummaryRow label="Partner payout" value={money.format(grossPayout)} bold/></div></div></div>;return <aside className="xl:self-stretch"><div className="xl:hidden">{card}</div><div ref={anchorRef} className="hidden h-px w-full xl:block" aria-hidden="true"/>{position&&typeof document!=="undefined"?createPortal(<div className="fixed z-30" style={{left:position.left,width:position.width,top:position.top}}>{card}</div>,document.body):null}</aside>;}
function SummaryRow({label,value,bold,accent,tone="neutral"}:{label:string;value:string;bold?:boolean;accent?:boolean;tone?:"positive"|"negative"|"neutral"}){const toneClass=tone==="positive"?"text-[#14845B]":tone==="negative"?"text-[#C63E45]":accent?"text-[#4F46E5]":"text-[#17365D]";return <div className="flex items-center justify-between gap-3 py-2.5"><span className={`text-[10.5px] ${bold?"font-semibold text-[#344054]":"font-medium text-[#667085]"}`}>{label}</span><span className={`text-[11px] ${bold?"font-bold":"font-semibold"} ${toneClass}`}>{value}</span></div>;}
function ValidationErrorDialog'''
new_text, count = re.subn(pattern, replacement, text, count=1)
if count != 1:
    raise SystemExit(f'LiveSummary block replacement count={count}')

path.write_text(new_text, encoding='utf-8')
